def _guard_running_pump(s, ctx, dev, site, peers, smp):
    """A live pipe sample stops a running pump on stale tank data or full level."""
    if not smp.pump_on or not -2 <= (utcnow() - smp.ts).total_seconds() <= commands.TANK_MAX_AGE_S:
        return
    tank_peer = peers.get("tank")
    if tank_peer is None:
        return  # legacy standalone pipe; the demo always has a paired tank
    tank = s.get(Device, tank_peer.id)
    age = (utcnow() - site.level_ts).total_seconds() if site.level_ts else None
    if tank is None or tank.state != "Active" or not tank.online or age is None or not -2 <= age <= commands.TANK_MAX_AGE_S:
        if not _throttled(dev.id, "level_stale_off", 2):
            ctx.actions.append(_pump_action(dev.id, "off", None, "guard:STALE_LEVEL"))
    elif site.level is not None and site.level >= float(_config(s, tank.id)["high_pct"]):
        if not _throttled(dev.id, "high_off", 2):
            ctx.actions.append(_pump_action(dev.id, "off", None, "auto:HIGH_LEVEL"))

    if reason_codes and all(not code.is_failure for code in reason_codes):
        self._ready.set()
    else:
        log.error("dynsec response subscription rejected")

def _on_disconnect(self, client, userdata, disconnect_flags, reason_code, properties):
    self._ready.clear()
    self._role_ready = False

TANK_MAX_AGE_S = 5  # demo level interval is 1s


def check_paired_tank(s: Session, dev: Device) -> None:
    """Guard manual ON in a paired site; retain legacy standalone pipe support."""
    if dev.site_id is None:
        return
    tank = s.scalar(select(Device).where(Device.site_id == dev.site_id, Device.type == "tank"))
    if tank is None or tank.state != "Active" or not tank.online:
        raise Conflict("Node bồn cùng site chưa sẵn sàng; không bật bơm")
    sample = s.scalar(select(Telemetry).where(Telemetry.device_id == tank.id)
                      .order_by(Telemetry.ts.desc(), Telemetry.id.desc()).limit(1))
    age = (utcnow() - sample.ts).total_seconds() if sample is not None else None
    if age is None or not -2 <= age <= TANK_MAX_AGE_S or sample.level_pct is None:
        raise Conflict("Chưa có mực nước mới trong 5 giây; không bật bơm")
    if sample.level_pct >= float(get_config(s, tank.id)["high_pct"]):
        raise Conflict("Bồn đã đạt mức đầy; không bật bơm")

from contextlib import contextmanager
from datetime import datetime, timezone

from sqlalchemy import create_engine, event
from sqlalchemy.orm import DeclarativeBase, sessionmaker

from .config import settings

if settings.is_sqlite:
    # check_same_thread=False: backend dùng nhiều thread (MQTT, watcher, request), mỗi kết nối chỉ một thread dùng tại một thời điểm.
    # timeout: thread ghi đến sau đợi tối đa 15 giây thay vì báo "database is locked" ngay.
    _connect_args = {"timeout": 15, "check_same_thread": False}
elif settings.database_url.startswith("mysql"):
    _connect_args = {"init_command": "SET time_zone='+00:00'"}
else:
    _connect_args = {}
engine = create_engine(settings.database_url, pool_pre_ping=True, pool_recycle=1800,
                       connect_args=_connect_args)

if settings.is_sqlite:
    @event.listens_for(engine, "connect")
    def _sqlite_pragmas(dbapi_connection, _record):
        cur = dbapi_connection.cursor()
        cur.execute("PRAGMA journal_mode=WAL")       # người đọc không chặn người ghi
        cur.execute("PRAGMA synchronous=NORMAL")     # an toàn với WAL, nhanh hơn FULL
        cur.execute("PRAGMA foreign_keys=ON")        # SQLite mặc định KHÔNG thực thi khóa ngoại
        cur.close()
SessionLocal = sessionmaker(bind=engine, expire_on_commit=False)


class Base(DeclarativeBase):
    pass


def utcnow() -> datetime:
    """Thời gian UTC dạng naive; toàn bộ DB lưu UTC."""
    return datetime.now(timezone.utc).replace(tzinfo=None)


@contextmanager
def session_scope():
    s = SessionLocal()
    try:
        yield s
        s.commit()
    except Exception:
        s.rollback()
        raise
    finally:
        s.close()


def get_db():
    """TV3 dependency interface; one short-lived Session per request."""
    session = SessionLocal()
    try:
        yield session
    finally:
        session.close()

"""TV2 Actor interface backed by the TV3 auth/RBAC package."""
from dataclasses import dataclass
from fastapi import Depends, Request
from .db import get_db
from .models import User
from .security.auth import get_current_user
from .security.rbac import require_role


@dataclass
class Actor:
    id: int
    role: str
    ip: str


def current_actor(request: Request, user: User = Depends(get_current_user)) -> Actor:
    return Actor(user.id, user.role, request.client.host if request.client else "")


def require_roles(*roles: str):
    def dependency(request: Request, user: User = Depends(require_role(*roles))) -> Actor:
        return Actor(user.id, user.role, request.client.host if request.client else "")
    return dependency


any_user = require_roles("Admin", "Operator", "Viewer")

@app.get("/api/ready")
def ready():
    """Readiness of DB, application subscriptions and dynsec; no credentials returned."""
    checks = {"database": False, "mqtt": False, "broker_admin": False}
    try:
        with engine.connect() as conn:
            conn.execute(text("SELECT 1"))
        checks["database"] = True
    except Exception:
        pass
    subscriber = get_subscriber()
    checks["mqtt"] = subscriber.client.is_connected() and subscriber.subscriptions_ready
    admin = get_broker_admin()
    checks["broker_admin"] = settings.broker_admin == "dynsec" and admin._ready.is_set()
    ok = all(checks.values())
    return JSONResponse({"status": "ready" if ok else "not_ready", "checks": checks}, status_code=200 if ok else 503)

def _on_subscribe(self, client, userdata, mid, reason_codes, properties) -> None:
    self.subscriptions_ready = bool(reason_codes) and all(not code.is_failure for code in reason_codes)
    if not self.subscriptions_ready:
        log.error("MQTT application subscriptions rejected")
